/**
 * Validate the two first real-topic textbook drafts (not autogenerated history).
 * Do not promote or index draft materials without explicit user approval.
 */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {getChapters} from '../notebook-templates.mjs';
const spec=[
 ['docs/review-drafts/gpc-clusters-2026-10-21.md','culture',['2026-09-09','2023-11-17','2026','CoNS','MRSA','MSSA']],
 ['docs/review-drafts/mssa-bacteremia-2026-10-21.md','infection',['2026-09-09','2025','再血培','14日','CEZ','TEE']]
];
const index=JSON.parse(fs.readFileSync('content/index.json','utf8'));
const originalMssa=fs.readFileSync('content/notes/mssa-bacteremia.md','utf8');
for(const [filename,category,needles] of spec){
 const text=fs.readFileSync(filename,'utf8');
 const headings=text.split('\n').filter(x=>/^## [1-8]\. /.test(x));
 const expected=getChapters(category).map((c,i)=>'## '+(i+1)+'. '+c.title);
 assert.deepEqual(headings,expected,filename+' must have exactly eight recognized chapters');
 assert.match(text,/医学的未承認|医学的未承認の草案/,'Draft must be clearly unapproved');
 assert.ok(text.includes('https://www.idsociety.org/practice-guideline/staphylococcus-aureus-bacteremia/'));
 for(const needle of needles)assert.ok(text.includes(needle),filename+' missing '+needle);
 assert.ok(text.length>3500,'Need educational explanations, not an index-only note');
 assert.equal(index.notes.includes(filename),false,'Review draft must not be visible as an official note');
 assert.equal(index.weekly.includes(filename),false,'Review draft must not be disguised as an actual daily Weekly');
 assert.ok(!/patient[\s_-]?id[:：]\s*\d+|患者名[:：]\s*|当院症例|院内限定/i.test(text),'Do not commit private records');
 assert.ok(!/https:\/\/(?:chatgpt.com\/c|chat.openai.com\/c)\//i.test(text),'Private conversation URLs prohibited');
 assert.ok(!/(?:OPENAI_API_KEY|api.openai.com)/.test(text),'No API credentials/requests');
 assert.ok(!text.includes('status: verified'),'Review-only draft cannot claim medical verification');
}
assert.match(originalMssa,/^status: draft$/m);
assert.ok(originalMssa.includes('# 治療期間とフォロー'), 'The existing MSSA note is still unchanged');
assert.ok(!index.notes.some(x=>x.startsWith('docs/review-drafts/')));
console.log('Two detailed evidence-linked textbooks validated: 8 mapped chapters each; reviews only; no public app or clinical changes.');
